var scene = UnityEngine.SceneManagement.SceneManager.GetSceneByName("City");
if (!scene.IsValid()) { Debug.LogError("City scene not loaded"); return; }
var roots = scene.GetRootGameObjects();
Sim.Jobs.JobCompletionResultPanel comp = null;
foreach (var r in roots) {
    comp = r.GetComponentInChildren<Sim.Jobs.JobCompletionResultPanel>(true);
    if (comp != null) break;
}
if (comp == null) { Debug.LogError("JobCompletionResultPanel not found"); return; }
var modal = comp.transform.Find("Modal");
if (modal == null) { Debug.LogError("Modal not found"); return; }
var so = new UnityEditor.SerializedObject(comp);
so.Update();
var ratingTMP = modal.Find("Rating")?.GetComponent<TMPro.TMP_Text>();
if (ratingTMP != null) so.FindProperty("ratingLabel").objectReferenceValue = ratingTMP;
var scoreTMP = modal.Find("Score")?.GetComponent<TMPro.TMP_Text>();
if (scoreTMP != null) so.FindProperty("scoreLabel").objectReferenceValue = scoreTMP;
var breakdownTMP = modal.Find("Breakdown")?.GetComponent<TMPro.TMP_Text>();
if (breakdownTMP != null) so.FindProperty("breakdownLabel").objectReferenceValue = breakdownTMP;
so.ApplyModifiedProperties();
UnityEditor.SceneManagement.EditorSceneManager.MarkSceneDirty(scene);
Debug.Log("[Wire] labels done. rating=" + (ratingTMP != null) + " score=" + (scoreTMP != null) + " breakdown=" + (breakdownTMP != null));
